suppressPackageStartupMessages({library(ggridges); library(ggdensity); library(ggplot2); library(Seurat)})
setwd(dirname(sub("--file=","",grep("--file=",commandArgs(FALSE),value=TRUE))))
so <- readRDS("../_data/zeisel_seurat.rds"); df <- FetchData(so, c("Snap25","Mbp","celltype","nFeature_RNA","umap_1","umap_2"))
g <- ggplot(df, aes(nFeature_RNA, celltype, fill = after_stat(x))) + geom_density_ridges_gradient(scale = 2.2, rel_min_height = .01) + scale_fill_viridis_c(option = "C", name = "genes") + theme_ridges() + labs(title = "ggridges gradient: genes per cell")
ggsave("v1_ridges_gradient.png", g, width = 7, height = 5.5, dpi = 140, bg = "white")
g <- ggplot(df, aes(Mbp, celltype, fill = celltype)) + stat_density_ridges(quantile_lines = TRUE, quantiles = 2, jittered_points = TRUE, position = position_points_jitter(height = 0), point_size = .2, point_alpha = .3, alpha = .7) + theme_ridges() + theme(legend.position = "none") + labs(title = "ggridges: Mbp with median + rug points")
ggsave("v2_ridges_points.png", g, width = 7, height = 5.5, dpi = 140, bg = "white")
g <- ggplot(df, aes(umap_1, umap_2, fill = celltype)) + geom_hdr(probs = c(.95, .8, .5), alpha = .5) + geom_point(size = .05, alpha = .2) + theme_minimal() + coord_fixed() + labs(title = "ggdensity::geom_hdr: highest-density regions")
ggsave("v3_hdr_umap.png", g, width = 8, height = 6, dpi = 140, bg = "white")
g <- ggplot(df, aes(umap_1, umap_2)) + geom_hdr_lines(aes(color = celltype), probs = c(.9, .5)) + theme_void() + coord_fixed() + labs(title = "geom_hdr_lines contours")
ggsave("v4_hdr_lines.png", g, width = 7.5, height = 6, dpi = 140, bg = "white")
